<script setup lang="ts">const{session,requests,tenants,authorizedTenantAudit,load,formatDate}=usePlatformAdminWorkspace();const selected=ref(''),loading=ref(false),error=ref(''),format=ref<'csv'|'xlsx'>('xlsx');const auditRequests=computed(()=>requests.value.filter(request=>request.category==='audit'&&request.decision==='approved'&&Boolean(request.expiresAt&&new Date(request.expiresAt).getTime()>Date.now())));const label=(request:any)=>`${request.id} - ${request.subject}`;const open=async()=>{const request=auditRequests.value.find(item=>item.id===selected.value);const tenant=request&&tenants.value.find(item=>item.id===request.tenantId);if(!request||!tenant)return;loading.value=true;error.value='';try{const events=await session.request<any[]>(`/api/platform-admin/tenants/${encodeURIComponent(tenant.id)}/audit?accessRequestId=${encodeURIComponent(request.id)}`);authorizedTenantAudit.value={tenant,accessRequestId:request.id,events}}catch(cause:any){error.value=cause?.data?.error||cause?.message||'Nao foi possivel carregar os eventos autorizados.'}finally{loading.value=false}};const exportAudit=async()=>{if(!authorizedTenantAudit.value)return;loading.value=true;try{await session.download(`/api/platform-admin/tenants/${encodeURIComponent(authorizedTenantAudit.value.tenant.id)}/audit-export?accessRequestId=${encodeURIComponent(authorizedTenantAudit.value.accessRequestId)}&format=${format.value}`,`Relatorio_Auditoria_de_Empresa.${format.value}`)}catch(cause:any){error.value=cause?.data?.error||cause?.message||'Nao foi possivel exportar os eventos.'}finally{loading.value=false}};onMounted(()=>void load({requests:true,tenants:true}))</script>
<template><div><p v-if="error" class="feedback feedback--error">{{error}}</p><section v-if="authorizedTenantAudit" class="panel"><div class="panel-head"><div><h2>Eventos de {{authorizedTenantAudit.tenant.name}}</h2><p>Acesso temporario validado</p></div><div class="inline-actions"><select v-model="format"><option value="xlsx">Excel (.xlsx)</option><option value="csv">CSV (.csv)</option></select><button class="button button--primary" :disabled="loading" @click="exportAudit">Exportar</button><button class="button button--quiet" @click="authorizedTenantAudit=null">Fechar</button></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Acao</th><th>Origem</th><th>Recurso</th></tr></thead><tbody><tr v-for="event in authorizedTenantAudit.events" :key="event.id"><td>{{formatDate(event.createdAt)}}</td><td><strong>{{event.summary}}</strong><small>{{event.context}}</small><code>{{event.action}}</code></td><td>{{event.actorType}}</td><td>{{event.entityType}} {{event.entityId}}</td></tr><tr v-if="!authorizedTenantAudit.events.length"><td colspan="4" class="empty-state">Nenhum evento encontrado no escopo autorizado.</td></tr></tbody></table></div></section><section v-else class="panel"><div class="panel-head"><div><h2>Consultar uma empresa</h2><p>Selecione uma autorizacao LGPD aprovada para carregar os eventos.</p></div></div><div class="inline-actions"><select v-model="selected" aria-label="Protocolo autorizado"><option value="">Selecione uma autorizacao aprovada</option><option v-for="request in auditRequests" :key="request.id" :value="request.id">{{label(request)}}</option></select><button class="button button--primary" :disabled="loading||!selected" @click="open">Carregar eventos</button></div></section></div></template>
